2px 0 0;color:var(--muted);font-size:15px;line-height:1.65}.count{flex:0 0 auto;padding:10px 14px;border:1px solid rgba(35,103,166,.14);border-radius:999px;color:var(--blue);background:#fff;font-size:12px;font-weight:900;box-shadow:0 8px 20px rgba(15,58,95,.08)}.legend{display:flex;flex-wrap:wrap;gap:9px;margin:0 0 20px}.tier{display:inline-flex;align-items:center;gap:7px;padding:7px 10px;border-radius:999px;background:#fff;color:#43566a;font-size:11px;font-weight:800;box-shadow:0 5px 14px rgba(15,58,95,.07)}.tier::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--tier-color)}.leaders{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:18px}.leader{position:relative;overflow:hidden;display:grid;grid-template-columns:88px minmax(0,1fr);gap:16px;min-height:178px;padding:20px;border:1px solid rgba(15,58,95,.1);border-radius:20px;background:rgba(255,255,255,.94);box-shadow:0 15px 34px rgba(15,58,95,.1);transition:transform .16s ease,box-shadow .16s ease}.leader::before{content:"";position:absolute;inset:0 auto 0 0;width:5px;background:var(--tier-color)}.leader:hover{transform:translateY(-3px);box-shadow:0 20px 42px rgba(15,58,95,.16)}.portrait{width:88px;height:104px;border-radius:16px;object-fit:cover;object-position:50% 24%;box-shadow:0 10px 23px rgba(15,58,95,.16)}.leader h2{margin:0;color:var(--navy);font-size:18px;line-height:1.2}.role{display:block;margin-top:5px;color:var(--blue);font-size:12px;font-weight:800;line-height:1.35}.org{display:block;margin-top:9px;color:#40566b;font-size:13px;line-height:1.4}.meta{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}.badge{padding:5px 8px;border-radius:999px;background:#eef5f8;color:#52677b;font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.04em}.profile-link{display:inline-flex;margin-top:12px;color:var(--blue);font-size:12px;font-weight:900;text-decoration:none}.profile-link:hover{text-decoration:underline}.dual-role{grid-column:1/-1;margin-top:4px;padding:16px 18px;border:1px solid rgba(198,149,45,.25);border-radius:16px;background:linear-gradient(135deg,#fffaf0,#fff);color:#5e4b1d;font-size:13px;line-height:1.55}.dual-role strong{color:#8b6717}@@media(max-width:760px){.shell{grid-template-columns:1fr}.sidebar{position:static;height:auto}.nav{grid-template-columns:repeat(2,minmax(0,1fr))}.nav details{grid-column:1/-1}.content{padding:24px 18px 38px}.topbar{display:block}.count{display:inline-flex;margin-top:16px}.leaders{grid-template-columns:1fr}}@@media(max-width:430px){.leader{grid-template-columns:70px minmax(0,1fr);padding:17px}.portrait{width:70px;height:88px}}
